  "help.freeAfterDues": "পুনরাবৃত্ত এবং সক্রিয় বিল থেকে আয় বিয়োগ আনুমানিক মাসিক বকেয়া।",
  "help.dueHeatmap": "পরবর্তী চার সপ্তাহের প্রতিটিতে কত বিল বকেয়া পড়বে এবং তাদের মোট পরিমাণ।",
  "help.debtTrend": "আমাদের কাছে স্ন্যাপশটগুলি আছে সবচেয়ে পুরানো এবং নতুন মাসের মধ্যে মোট খোলা ব্যালেন্সে পরিবর্তন৷",
  "help.chitInstallments": "বেশিরভাগ বড় চিট সমান মাসিক শেয়ার ব্যবহার করে (মূল্য ÷ মাস)। কিছু গ্রুপ ক্রমহ্রাসমান কিস্তি ব্যবহার করে (উচ্চ তাড়াতাড়ি, কম পরে)। আপনার গ্রুপের সাথে মেলে এমন টাইপ বেছে নিন।",
  "help.chitMonthsPaid": "আপনি ইতিমধ্যে কত কিস্তি পরিশোধ করেছেন। আপনি যদি 46 টাকা দেন, তাহলে আপনি এখন 47 মাসে আছেন। এটি বকেয়া পরিমাণ এবং মাসের সংখ্যা ঠিক করে।",
  "help.chitPayoutReceived": "আপনি যখন চিট নেন তখন প্রকৃত নগদ আপনি পেয়েছিলেন (যেমন ₹4,43,000)। আমরা এর থেকে নিলামে ডিসকাউন্ট নিয়ে কাজ করি — আপনাকে ডিসকাউন্ট অনুমান করার দরকার নেই।",
  "help.chitForeman": "আয়োজক কমিশন, প্রায়শই চিট মূল্যের প্রায় 5%, আপনি যখন টাকা পান তখন পাত্র থেকে নেওয়া হয়।",
  "help.chitDiscount": "নিলামে আপনি সম্পূর্ণ চিট মানের চেয়ে কম গ্রহণ করেন — এই ছাড়টি অন্যান্য সদস্যদের সাথে ভাগ করা হয়। আপনি সম্পূর্ণ চিট পরিমাণ নগদ পাবেন না।",
  "help.chitAdvisor": "আপনি যখন চিট নিতে পারেন সেই মাসগুলির তুলনা করুন: আনুমানিক ছাড়, ফোরম্যানের পরে অর্থপ্রদান, সেই মাসের আপনার অন্যান্য বিল এবং আপনি গ্রহণ করতে ইচ্ছুক সর্বাধিক ক্ষতি৷",
  "help.chitMaxLoss": "আমরা আপনার আয়, মাসিক বকেয়া, খোলা ঋণ, অতিরিক্ত বিল এবং সঞ্চয় থেকে সর্বাধিক ক্ষতির পরামর্শ দিই - একটি নির্দিষ্ট % নয়। তাড়াতাড়ি গ্রহণ প্রায়ই এটি অতিক্রম করে; পরবর্তী মাস সাধারণত কম খরচ হয়।",
  "help.loanExtraTiming": "আসন্ন মাসগুলি দেখায়: যখন অন্যান্য বিল হালকা হয় যাতে আপনি এই লোনে অতিরিক্ত অর্থ প্রদান করতে পারেন, এবং ভারী মাসগুলি যখন আপনার সর্বনিম্ন থাকা উচিত।",
  "help.incomeEntryBasis": "টেক-হোম ট্যাক্স, PF এবং স্থির কর্তনের পরে আপনার ব্যাঙ্কে যা আসে তা মেলে — চাপ এবং বিনামূল্যে-নগদ গণিতের জন্য সেরা৷ স্থূল শুধুমাত্র উপযোগী যদি আপনি প্রবেশ করা প্রতিটি নম্বর প্রাক-কর হয়; বিনামূল্যে নগদ আপনার প্রকৃত ব্যাঙ্ক ব্যালেন্সের চেয়ে কম দেখা যেতে পারে যদি টেক-হোম আয় মোটের থেকে কম হয়।",
  "help.householdPayerBillTag": "পারিবারিক মোডের জন্য ঐচ্ছিক: ট্যাগ যারা অর্থ প্রদান করে যাতে পরিবারের নাড়ি বিভক্ত দায়িত্ব বর্ণনা করতে পারে। মোট এবং চাপের গণিত একই থাকে।",
