  "guide.household.shareTitle": "আপনি কি শেয়ার করেন তা নিয়ন্ত্রণ করুন",
  "guide.household.shareText": "আপনি সিদ্ধান্ত নিন পরিবারের সদস্যরা কি দেখতে পাবেন। অন্যদের আপনার প্রতিদিনের খরচ দেখতে দেওয়ার জন্য শেয়ার খরচ টগল করুন। আপনার প্রতিশ্রুতি তালিকা ভাগ করতে বিল নাম টগল করুন.",
