  "guide.pulse.freeCashTitle": "Free নগদ",
  "guide.pulse.freeCashText": "এই মাসে আপনার সমস্ত প্রতিশ্রুতিবদ্ধ অর্থপ্রদানের পরে টাকা অবশিষ্ট আছে। এটি আপনাকে আসলে ব্যয়, সঞ্চয় বা বিনিয়োগ করতে হবে।",
