  "profileHub.scoreWhy.pressure.what": "আপনার আয়ের কতটা বিল এবং ওভারডিউ আইটেমে আটকে আছে তা পরিমাপ করে।",
  "profileHub.scoreWhy.pressure.high": "আয়ের সাপেক্ষে অনেক বিল শীঘ্রই বা অতিরিক্ত বকেয়া আছে।",
  "profileHub.scoreWhy.pressure.mid": "আয়ের একটি লক্ষণীয় অংশ পুনরাবৃত্ত বকেয়াতে যায়।",
  "profileHub.scoreWhy.pressure.low": "বিলগুলি এখন আয়ের তুলনায় পরিচালনাযোগ্য।",
  "profileHub.scoreWhy.health.what": "বিলের বোঝা, অর্থপ্রদানের অভ্যাস, সঞ্চয় বাফার এবং ঋণের প্রবণতাকে একত্রিত করে।",
  "profileHub.scoreWhy.health.low": "বোঝা, বাফার, বা অর্থপ্রদানের সামঞ্জস্যের দুর্বলতা এটিকে কমিয়ে দিচ্ছে।",
  "profileHub.scoreWhy.health.mid": "কিছু এলাকায় কঠিন — কয়েকটি অভ্যাস বা বাফার এটিকে উত্তোলন করতে পারে।",
  "profileHub.scoreWhy.health.good": "সামগ্রিক অভ্যাস এবং বাফার স্বাস্থ্যকর দেখায়।",
  "profileHub.scoreWhy.runway.what": "আয় থেমে গেলে আপনি প্রয়োজনীয় জিনিসগুলি কভার করতে পারবেন (তরল সঞ্চয় + বিনামূল্যে নগদ)।",
  "profileHub.scoreWhy.runway.critical": "খুব পাতলা কুশন — একটি আয় শক শোষণ করা কঠিন হবে.",
  "profileHub.scoreWhy.runway.thin": "একটি আরামদায়ক 3-6 মাসের রিজার্ভের নীচে।",
  "profileHub.scoreWhy.runway.ok": "রানওয়ে আপাতত নিরাপদ পরিসরে।",
  "profileHub.scoreWhy.flexibility.what": "নির্দিষ্ট মাসিক বকেয়া পরে আপনার কত রুম আছে।",
  "profileHub.scoreWhy.flexibility.low": "বেশিরভাগ আয় ইতিমধ্যেই পুনরাবৃত্ত বিলের জন্য প্রতিশ্রুতিবদ্ধ।",
  "profileHub.scoreWhy.flexibility.ok": "আপনি প্রতি মাসে অর্থপূর্ণ বিনামূল্যে নগদ ধরে রাখেন।",
  "profileHub.scoreWhy.debt.what": "EMI এবং মাসিক আয়ের একটি ভাগ হিসাবে ঋণ প্রদান।",
  "profileHub.scoreWhy.debt.high": "EMI লোড ভারী — নতুন ঋণ নগদ প্রবাহকে চাপ দেবে।",
  "profileHub.scoreWhy.debt.ok": "ঋণ পরিশোধ একটি পরিচালনাযোগ্য ব্যান্ডের মধ্যে হয়।",
  "profileHub.scoreWhy.lending.what": "আপনি ঋণ দেওয়া বা প্রাপ্ত সময়মতো পরিশোধের ট্র্যাক করে।",
  "profileHub.scoreWhy.lending.empty": "এখনও কোন ঋণ এন্ট্রি নেই — এই স্কোর তৈরি করতে ডিল এবং লগ পরিশোধ যোগ করুন।",
  "profileHub.scoreWhy.lending.low": "দেরিতে বা আংশিক পরিশোধ বিশ্বাসকে কমিয়ে দেয়।",
  "profileHub.scoreWhy.lending.ok": "পরিশোধের ইতিহাস নির্ভরযোগ্য দেখায়।",
  "profileHub.scoreFix.pressure.clearOverdue": "আগে বকেয়া বিলগুলি সাফ করুন — তারা এই স্কোরটিকে সবচেয়ে বেশি ক্ষতি করে।",
  "profileHub.scoreFix.pressure.trimSubscriptions": "সদস্যতা পর্যালোচনা করুন এবং ঐচ্ছিক EMIs আপনি বিরতি দিতে পারেন।",
  "profileHub.scoreFix.pressure.payOnTime": "চাপ স্থিতিশীল করতে এই মাসে নির্ধারিত তারিখের আগে অর্থ প্রদান করুন।",
  "profileHub.scoreFix.runway.buildReserve": "প্রতিটি বেতনের দিনে একটি নির্দিষ্ট পরিমাণ তরল সঞ্চয় করুন।",
  "profileHub.scoreFix.runway.reduceBurn": "রানওয়ে প্রসারিত করতে অ-প্রয়োজনীয় পুনরাবৃত্ত বিল ট্রিম করুন।",
  "profileHub.scoreFix.health.reduceBurden": "উচ্চ-বোঝার প্রতিশ্রুতিগুলি হ্রাস করুন বা পুনরায় নির্ধারণ করুন।",
  "profileHub.scoreFix.health.buildBuffer": "তরল সঞ্চয় ব্যয়ের টার্গেট 3-6 মাস।",
  "profileHub.scoreFix.health.payOnTime": "একটি পেমেন্ট স্ট্রীক রাখুন — প্রতিটি বিল পেমেন্ট লগ.",
  "profileHub.scoreFix.health.reduceDebt": "প্রথমে সর্বোচ্চ সুদের ব্যালেন্সে চিপ করুন।",
  "profileHub.scoreFix.health.keepGoing": "Keep current habits — you're on track.",
  "profileHub.scoreFix.health.general": "আয়, বিল এবং সঞ্চয় লগ করুন যাতে স্কোর সঠিক থাকে।",
  "profileHub.scoreFix.flexibility.reduceBurden": "কম পুনরাবৃত্ত বকেয়া অথবা যেখানে সম্ভব EMI আলোচনা করুন।",
  "profileHub.scoreFix.flexibility.trackSpend": "লগ পরিবর্তনশীল খরচ তাই বিনামূল্যে নগদ বাস্তবতা মেলে.",
  "profileHub.scoreFix.debt.attackHighInterest": "পে অর্ডারে ক্রেডিট কার্ড এবং উচ্চ হারের ঋণকে অগ্রাধিকার দিন।",
  "profileHub.scoreFix.debt.avoidNewEmi": "নতুন EMI এড়িয়ে চলুন যতক্ষণ না ওভারলোড আয়ের ~35% এর নিচে নেমে আসে।",
  "profileHub.scoreFix.lending.onTime": "সম্মত তারিখে ঋণের কিস্তি সংগ্রহ করুন বা পরিশোধ করুন।",
  "profileHub.scoreFix.lending.addDeals": "ট্রাস্ট ট্র্যাকিং শুরু করতে লেনদেন পৃষ্ঠা থেকে একটি ঋণ এন্ট্রি যোগ করুন।",
